# -*- coding: utf-8 -*-
"""dpr_rollback_v635_to_v634.py — 把 dpr_suite.py v635 逐位元組還原成 v634（R-1002-26 E6 備份閘·R-1003-28）
用法：python3 dpr_rollback_v635_to_v634.py dpr_suite.py dpr_suite_v634.py
做法：從 v635 的 _PACK 取出回填字典 v96 → 移除 R-1003-28 新增的 b3_replies 134 筆／map 1 鍵／rulings 1 筆／orders 2 筆／
      rule_R_1003_28、note_v96，還原 version／updated／count／map_note → 以 dict_v14_codec 重新編碼為 v95 → 放回 _PACK；
      再還原 docstring 與 SUITE_VERSION。成功時印出 SHA256 522b1a14… ✅（v634 原檔）。
"""
import sys, re, json, base64, lzma, hashlib, types
EXPECT_IN = '1aed286042e512ac40d970494d635dcbe40441f77b2a500bcb088186496cbfd5'
EXPECT_OUT = '522b1a1439c548c3e45b9f30892b75b9b300593cb36b9231ba16d06697428987'
DOC_NEW = '"""dpr_suite.py — DPR 迴歸/迴路單檔套件（v635·1003 R-1003-28 T組 1002 回填攝取）\nv635（2026-10-03·**R-1003-28**·Amber 林彥博「回填更新」＋「BQ是報關，歸類到未到出貨日」「系統需刪改」「LTS是Deckers集團的報告上傳系統…」「只記原因、續追」）：\n  · 回填字典 v95→**v96**：b3_replies +134（未到客戶交期 126／系統需刪改 3／其他 5）、map +1（CHUA DEN NGAY GIAO DOI BQ→未到客戶交期）；\n    orders 2,314→2,316（4 表 011580 AMARA H411349767-100BH、20260925A-20L 原因存證·answer_rejected 續列）。phrase_classifier v35 一行未動。\n  · 只換 _PACK 字典；builder v603、23 棒、快照 v579、NT/NS v513、overrides v1.11、判定式一行未動。10/3 T組重建：只 B3 前次回覆／追問判定 87 列＋4 表歷史欄 2 格＋說明頁版本字串。SUITE_VERSION 634 → 635（R-v556-1）。\n'
DOC_OLD = '"""dpr_suite.py — DPR 迴歸/迴路單檔套件（v634·1003 R-1003-27 報延天數表 NA 不顯示）\n'
VER_NEW, VER_OLD = 'SUITE_VERSION = 635   #', 'SUITE_VERSION = 634   #'
MAP_NOTE_OLD = '正規化（去聲調·大寫·去標點）後精確比對；三選一中越原文 6 句＋CHUA TOI ETD NGAY GIAO KH（Claude 對譯為「未到客戶交期」·**Amber 0928 確認**「未到交期，未到期不要詢問」R-0928-8）。未命中＝其他（保留原文、請改填三選一）'
B3_ADDED = ['DGT-20260612A-2FT#11', 'DGT-20260612A-1FT#11', 'DGT-20260804A-8CT#11', 'DGT-20260804A-9CT#11', 'DGT-H411400349-180#11', 'H411413633-80#11', 'H411413006-80#11', 'H411412964-80#11', 'H411412964-20#11', 'H411412964-50#11', 'H411413006-50#11', 'H411413006-100#11', 'H411413006-90#11', 'H411413006-130#11', 'H411413006-150#11', '20260923A-12#11', '20260923A-4#11', '20260923A-11#11', 'H411415077-30#11', 'H411415077-60#11', 'H411415071-100#11', 'H411415071-220#11', 'H411415071-170#11', 'H411415071-190#11', 'H411417652-20#11', 'H411415071-140#11', 'H411415071-240#11', 'H411415071-400#11', 'H411415071-390#11', 'H411415071-500#11', 'H411415071-510#11', 'H411415071-490#11', 'H411415071-520#11', 'H411415071-320#11', 'H411415071-310#11', 'H411415071-340#11', 'H411415071-350#11', 'H411415071-360/3#11', 'H411415071-360/2#11', 'H411415071-330#11', 'H411415071-470#11', 'H411415071-450#11', 'H411415071-460#11', 'H411415071-480#11', 'H411415071-420#11', 'H411428113-30#11', 'H411428113-40#11', 'H411428146-220#11', 'H411428146-190#11', 'H411428146-230#11', 'H411428146-210#11', 'H411428146-120#11', 'H411428146-110#11', 'H411428146-140#11', 'H411428146-130#11', 'H411428146-70#11', 'H411428146-100#11', 'H411428157-100#11', 'H411428157-110#11', 'H411428157-40#11', 'H411428157-50#11', 'H411428113-70#11', 'H411428113-50#11', 'H411428113-80#11', 'H411428113-100/#11', 'H411428113-110#11', 'H411428113-110/1#11', 'H411431447-20#11', 'H411431107-50#11', 'H411428161-10#11', 'H411431230-30#11', 'H411431230-10#11', 'H411428161-30#11', 'H411349767BH#12', 'H411418947-50#11', 'H411418950-30#11', 'H411418950-70#11', 'H411418950-100#11', 'H411429253-440#11', 'H411418950-150#11', 'H411418950-40#11', 'H411431596-210#11', 'H411431596-220#11', 'H411430551-60#11', 'H411431596-250#11', 'H411431596-290#11', 'H411426491-40#11', 'H411429253-220#11', 'H411431596-20#11', 'H411429253-180#11', 'H411429253-180/2#11', 'H411429253-180/1#11', 'H411431596-30#11', 'H411429253-160#11', 'H411429253-170#11', 'H411426491-10#11', 'H411426491-30#11', 'H411429253-140#11', 'H411429253-150#11', 'H411429253-130#11', 'H411429253-110#11', 'H411430551-20#11', 'H411429253-100#11', 'H411429253-30#11', 'H411429253-10#11', 'H411426491-20#11', 'H411430551-30#11', 'H411431596-40#11', 'H411431596-50#11', 'H411429253-20#11', 'H411431596-80#11', 'H411429253-190#11', 'H411429253-190/1#11', 'H411431596-70/1#11', 'H411426491-60#11', 'H411426491-70#11', 'H411431596-90#11', 'H411426491-50#11', 'H411426491-80#11', 'H411431596-170#11', 'H411431596-100#11', 'H411431596-150#11', 'H411429253-330#11', 'H411429253-310#11', 'H411429253-290#11', 'H411429253-340#11', 'H411426491-90#11', 'H411426491-110#11', 'H411429253-450#11', 'H411429253-460#11', 'H411429253-410#11', 'H411426491-120#11', 'H411429253-430#11', 'H411429253-400#11']
ORD_ADDED = ['H411349767-100BH', '20260925A-20L']
src, dst = sys.argv[1], sys.argv[2]
raw = open(src, 'rb').read()
assert hashlib.sha256(raw).hexdigest() == EXPECT_IN, '輸入不是 v635（SHA256 不符）'
t = raw.decode('utf-8')
def blob(name):
    m = re.search(r"    '%s': '([A-Za-z0-9+/=]+)'" % re.escape(name), t); return m
codec = types.ModuleType('dict_v14_codec')
exec(lzma.decompress(base64.b64decode(blob('dict_v14_codec.py').group(1))).decode('utf-8'), codec.__dict__)
m96 = blob('回填原因處置字典_v96_columnar.json')
D = codec.decode(json.loads(lzma.decompress(base64.b64decode(m96.group(1))).decode('utf-8')))
b3 = D['b3_replies']
for k in B3_ADDED: del b3['items'][k]
del b3['map']['CHUA DEN NGAY GIAO DOI BQ']; b3['map_note'] = MAP_NOTE_OLD
assert b3['rulings'][-1]['rule'] == 'R-1003-28'; b3['rulings'].pop()
for k in ORD_ADDED: del D['orders'][k]
del D['rule_R_1003_28']; del D['note_v96']
D['version'], D['updated'], D['count'] = 'v95', '2026-09-30', len(D['orders'])
p95 = json.dumps(codec.encode(D), ensure_ascii=False, separators=(',', ':')).encode('utf-8')
b95 = base64.b64encode(lzma.compress(p95, preset=9 | lzma.PRESET_EXTREME)).decode('ascii')
t = t[:m96.start()] + "    '回填原因處置字典_v95_columnar.json': '" + b95 + "'" + t[m96.end():]
assert t.count(DOC_NEW) == 1 and t.count(VER_NEW) == 1
t = t.replace(DOC_NEW, DOC_OLD, 1).replace(VER_NEW, VER_OLD, 1)
out = t.encode('utf-8'); h = hashlib.sha256(out).hexdigest()
open(dst, 'wb').write(out)
print('SHA256', h[:8] + '…', '✅' if h == EXPECT_OUT else '❌ 不符')
sys.exit(0 if h == EXPECT_OUT else 1)
